<?php
/**
 * Marketing OS M10 Dev-only right-side L3 workbench.
 * Left-side L2/L3 is exclusively generated by Andy Core registry.
 * Reuses M7 nonce/revision/Dev-only draft storage. Never awards anything.
 */
if ( ! defined('ABSPATH') ) { exit; }
if ( ! current_user_can('manage_woocommerce') ||
    ! class_exists('Andy_Commerce_M7_Draft_Studio') ||
    ! Andy_Commerce_M7_Draft_Studio::dev_only() ) {
    wp_die('此营销工作台仅供获授权的 Dev 管理员使用。','',array('response'=>403));
}
$tab = isset($_GET['tab']) ? sanitize_key(wp_unslash($_GET['tab'])) : 'marketing-promotions';
if ( ! in_array($tab,array('marketing-promotions','marketing-create','marketing-templates',
    'marketing-simulate','marketing-logs'),true) ) { wp_die('无效的营销页面。','',array('response'=>404)); }
$base = static function($target,$args=array()) {
    return add_query_arg(array_merge(array('page'=>'andy-commerce','tab'=>$target),$args),admin_url('admin.php'));
};
$types = array(
    'gift'=>array('type'=>'free_gift','label'=>'满额赠品','mark'=>'🎁','desc'=>'达到 USD 门槛，预览赠品资格'),
    'fixed'=>array('type'=>'spend_save','label'=>'满额立减','mark'=>'◆','desc'=>'达到 USD 门槛，减免固定金额'),
    'percent'=>array('type'=>'spend_save','label'=>'百分比折扣','mark'=>'%','desc'=>'达到 USD 门槛，按比例减免'),
    'bogo'=>array('type'=>'bogo','label'=>'买赠活动','mark'=>'⊞','desc'=>'按商品与数量配置买赠优惠'),
    'bundle'=>array('type'=>'bundles','label'=>'组合优惠','mark'=>'⬡','desc'=>'指定商品组合和折扣'),
    'tier'=>array('type'=>'tiered','label'=>'阶梯优惠','mark'=>'▥','desc'=>'按购买件数区分优惠')
);
$all = Andy_Commerce_M7_Draft_Studio::rows();
$edit = isset($_GET['draft_id']) && is_string($_GET['draft_id']) ? sanitize_key(wp_unslash($_GET['draft_id'])) : '';
$copy = isset($_GET['copy_id']) && is_string($_GET['copy_id']) ? sanitize_key(wp_unslash($_GET['copy_id'])) : '';
$chosen = null;
$copySource = false;
if ($edit !== '' && isset($all[$edit])) { $chosen=$all[$edit]; }
if ($copy !== '' && isset($all[$copy])) { $chosen=$all[$copy];$copySource=true; }
if (($edit !== '' || $copy !== '') && $chosen === null && $tab === 'marketing-create') {
    echo '<div class="notice notice-error"><p>活动草稿不存在或已归档。</p></div>';
}
$template = isset($_GET['template']) && is_string($_GET['template'])
    ? sanitize_key(wp_unslash($_GET['template'])) : 'gift';
if (!isset($types[$template])) $template='gift';
if ($chosen) {
    $rule=$chosen['rule']??array();
    $chosenType=$chosen['type']??'spend_save';
    $template=($chosenType==='free_gift'?'gift':
        ($chosenType==='bogo'?'bogo':($chosenType==='bundles'?'bundle':
        ($chosenType==='tiered'?'tier':(isset($rule['percent_bp'])?'percent':'fixed')))));
} else {
    $rule=match($template) {
        'fixed'=>array('threshold_minor'=>16900,'discount_minor'=>2000),
        'percent'=>array('threshold_minor'=>12900,'percent_bp'=>1000),
        'gift'=>array('threshold_minor'=>9900,'product_id'=>0),
        'tier'=>array('tiers'=>array(array('minimum_qty'=>2,'percent_bp'=>1000))),
        default=>array(),
    };
}
$draftName=$chosen?($chosen['name']??''):'';
$chosenId=$chosen && !$copySource ? ($chosen['id']??'') : '';
$revision=$chosen && !$copySource ? (int)($chosen['revision']??0) : 0;
$labelTypes=array('spend_save'=>'满额优惠','free_gift'=>'满额赠品',
    'bogo'=>'买赠活动','bundles'=>'组合优惠','tiered'=>'阶梯优惠');
$operationResults=array('saved'=>'已保存','archived'=>'已归档',
    'invalid'=>'输入数据无效','conflict'=>'草稿版本冲突','limit'=>'草稿数量达到上限');
?>
