<script>
(function(){
    var form=document.getElementById('andy-commerce-m10-draft-form');
    if(!form)return;
    var name=document.getElementById('ac-m10-live-name');
    var threshold=document.getElementById('ac-m10-live-threshold');
    var reward=document.getElementById('ac-m10-live-reward');
    function value(key){var el=form.querySelector('[name="'+key+'"]');return el?el.value:'';}
    function update(){
        name.textContent=value('draft_name')||'未命名草稿';
        var type=value('draft_type'),section='draft_rule_fields['+type+']';
        var t=value(section+'[threshold]');
        threshold.textContent=t?'USD $'+t:'按商品及数量规则';
        if(type==='free_gift')reward.textContent='赠品商品 ID：'+(value(section+'[product_id]')||'未填写');
        else if(type==='spend_save') {
            var mode=value(section+'[discount_mode]');
            reward.textContent=mode==='percent'?'减免 '+(value(section+'[percent]')||'0')+'%':
                '减免 USD $'+(value(section+'[fixed]')||'0');
        } else reward.textContent='请在左侧配置具体商品及数量规则';
    }
    form.addEventListener('input',update);
    form.addEventListener('change',update);
    update();
})();
</script>
